mapper.select:
SELECT 
FROM tb_courses
WHERE institution_id = #{institutionId}
  AND course_code = #{courseCode}
  AND deleted_at IS NULL

SELECT FROM tb_courses WHERE deleted_at IS NULL
AND ( LOWER(title) LIKE '%' || #{criteria.keyword} || '%' ESCAPE '\' OR EXISTS ( SELECT 1 FROM tb_institutions i WHERE i.id = institution_id AND LOWER(i.name) LIKE '%' || #{criteria.keyword} || '%' ESCAPE '\' ) OR EXISTS ( SELECT 1 FROM tb_course_instructors ci JOIN tb_users u ON u.id = ci.user_id WHERE ci.course_id = tb_courses.id AND LOWER(u.name) LIKE '%' || #{criteria.keyword} || '%' ESCAPE '\' ) )
AND education_type = #{criteria.educationType}
AND selection_method = #{criteria.selectionMethod}
AND classification_code LIKE #{criteria.classificationPrefix} || '%'
AND status = #{criteria.status}
ORDER BY
updated_at course_code title status start_date end_date created_at
ASC DESC , id ASC LIMIT #{criteria.limit} OFFSET #{criteria.offset}

SELECT COUNT(*) FROM tb_courses WHERE deleted_at IS NULL
AND ( status <> 'DRAFT'
OR institution_id IN
